const input = $input.first();
const rawJson = (input && input.json) || {};

let triggerSource = 'internal';
let rawBody = {};

try {
  const trigWebhook = $('Webhook Trigger (jira-push-spec)').first();
  if (trigWebhook && trigWebhook.json) {
    triggerSource = 'webhook';
    rawBody = trigWebhook.json.body || trigWebhook.json;
  }
} catch (e) {}

if (triggerSource !== 'webhook') {
  try {
    const trigExec = $('Execute Workflow Trigger').first();
    if (trigExec && trigExec.json) {
      triggerSource = 'internal';
      rawBody = trigExec.json.body?.params || trigExec.json.body || trigExec.json.params || trigExec.json;
    }
  } catch (e) {}
}

const payload = Object.assign({}, rawJson, rawBody);
const rawKey = payload.issueKey || '';
const rawProject = (payload.project || '').trim();
const userName = payload.userName || 'User';
const isDryRun = Boolean(payload.dryRun);
const isForce = Boolean(payload.force);
const markdownContent = typeof payload.markdownContent === 'string' ? payload.markdownContent : '';
const hasInlinePayload = markdownContent.trim().length > 0;
const attachments = Array.isArray(payload.attachments) ? payload.attachments : [];

const match = String(rawKey).match(/([A-Z][A-Z0-9]*-\d+)/i);
const issueKey = match ? match[1].toUpperCase() : '';

if (!issueKey) {
  const errMsg = `🚨 **[Lỗi Cú Pháp]** Không tìm thấy mã Jira \`issueKey\` hợp lệ trong lệnh.\n> Cú pháp: \`/agent [project] push-jira [issueKey]\`\n> Ví dụ: \`/agent 3.1 push-jira G3PTP-17396\``;
  return [{
    json: {
      isError: true,
      errorType: 'INVALID_ISSUE_KEY',
      reportText: errMsg,
      _triggerSource: triggerSource,
      userName
    }
  }];
}

return [{
  json: {
    isError: false,
    issueKey,
    project: rawProject,
    targetPath: 'spec',
    readContent: false,
    dryRun: isDryRun,
    force: isForce,
    filePath: payload.filePath || '',
    specType: payload.specType || '',
    callerWorkspaceDir: payload.callerWorkspaceDir || '',
    markdownContent,
    hasInlinePayload,
    attachments,
    userName,
    _triggerSource: triggerSource
  }
}];

const fs = require('fs');
const path = require('path');

const input = $input.first();
const resolveRes = (input && input.json) || {};
let prepContext = {};
try {
  prepContext = $('Prepare Resolver Input').first()?.json || {};
} catch (_) {}

const triggerSource = prepContext._triggerSource || resolveRes._triggerSource || 'internal';
const issueKey = prepContext.issueKey || resolveRes.issueKey || '';
const userName = prepContext.userName || resolveRes.userName || 'User';
const isDryRun = Boolean(prepContext.dryRun || resolveRes.dryRun);
const isForce = Boolean(prepContext.force || resolveRes.force);
const hasInlinePayload = Boolean(prepContext.hasInlinePayload && typeof prepContext.markdownContent === 'string');
const isExternalCaller = Boolean(hasInlinePayload || prepContext.callerWorkspaceDir);

let targetFilePath = '';
let specDir = '';
let specType = '';
let markdownContent = '';
let inlineAttachments = Array.isArray(prepContext.attachments) ? prepContext.attachments : [];

if (hasInlinePayload) {
  markdownContent = prepContext.markdownContent;
  targetFilePath = prepContext.filePath || `workspace/issues/${issueKey}/spec/refined.md`;
  specDir = path.dirname(targetFilePath);
  const isFinal = path.basename(targetFilePath).toLowerCase().includes('final');
  specType = prepContext.specType || (isFinal ? 'final.md (chuẩn ba-spec)' : 'refined.md (chuẩn ba-refine)');
} else {
  // 1. Kiểm tra kết quả từ Workspace Resolver (fallback khi chạy từ Slack / trong container)
  if (resolveRes.isError || !resolveRes.found) {
    return [{
      json: {
        isError: true,
        errorType: resolveRes.errorType || 'DIR_NOT_FOUND',
        reportText: resolveRes.reportText || `🚨 Không tìm thấy thư mục workspace cho ticket **${issueKey}**.`,
        _triggerSource: triggerSource,
        userName,
        issueKey
      }
    }];
  }

  specDir = resolveRes.resolvedPath || resolveRes.dirPath || '';
  const refinedPath = path.join(specDir, 'refined.md');
  const finalPath = path.join(specDir, 'final.md');

  if (fs.existsSync(refinedPath)) {
    targetFilePath = refinedPath;
    specType = 'refined.md (chuẩn ba-refine)';
  } else if (fs.existsSync(finalPath)) {
    targetFilePath = finalPath;
    specType = 'final.md (chuẩn ba-spec)';
  } else {
    return [{
      json: {
        isError: true,
        errorType: 'SPEC_NOT_FOUND',
        reportText: `🚨 **[Không Tìm Thấy Spec]** Ticket **${issueKey}** chưa có file đặc tả chuẩn trong thư mục:\n> \`${specDir}\`\n\n*👉 Cần có ít nhất 1 trong 2 file: \`spec/refined.md\` (từ ba-refine) hoặc \`spec/final.md\` (từ ba-spec) trước khi đẩy lên Jira.*`,
        _triggerSource: triggerSource,
        userName,
        issueKey
      }
    }];
  }

  try {
    markdownContent = fs.readFileSync(targetFilePath, 'utf8');
  } catch (e) {
    return [{
      json: {
        isError: true,
        errorType: 'READ_ERROR',
        reportText: `🚨 **[Lỗi Đọc File]** Không thể đọc nội dung file tại \`${targetFilePath}\`: ${e.message}`,
        _triggerSource: triggerSource,
        userName,
        issueKey
      }
    }];
  }

  // Thu thập ảnh local từ diagrams/ khi chạy ở Resolver Mode
  const diagramDir = path.join(specDir, 'diagrams');
  if (fs.existsSync(diagramDir)) {
    try {
      const files = fs.readdirSync(diagramDir).filter(f => /\.(png|jpe?g|svg)$/i.test(f));
      inlineAttachments = files.map(f => {
        const full = path.join(diagramDir, f);
        const ext = path.extname(f).toLowerCase();
        const mimeType = ext === '.svg' ? 'image/svg+xml' : (ext === '.jpg' || ext === '.jpeg' ? 'image/jpeg' : 'image/png');
        return {
          filename: f,
          mimeType,
          dataBase64: fs.readFileSync(full).toString('base64')
        };
      });
    } catch (_) {}
  }
}

if (!markdownContent.trim()) {
  return [{
    json: {
      isError: true,
      errorType: 'EMPTY_FILE',
      reportText: `🚨 **[File Spec Rỗng]** File tại \`${targetFilePath}\` không có nội dung.`,
      _triggerSource: triggerSource,
      userName,
      issueKey
    }
  }];
}

// 2. Pre-flight Quality Gate (Chuẩn ba-refine; bỏ qua khi --force hoặc final.md)
const isFinalSpec = path.basename(targetFilePath).toLowerCase().includes('final');
const qualityErrors = [];

if (!isForce && !isFinalSpec) {
  if (/\[\.\.\.\]/.test(markdownContent)) {
    qualityErrors.push("Spec còn chứa placeholder chưa điền: `[...]`");
  }

  const forbiddenSections = [
    /##\s*Giả định\s*(&|và)\s*Rủi ro/i,
    /##\s*Ngoài Phạm vi/i,
    /##\s*Đánh giá Độ tin cậy/i,
    /##\s*(?:🧱\s*)?Technical Notes/i
  ];
  for (const pattern of forbiddenSections) {
    if (pattern.test(markdownContent)) {
      qualityErrors.push(`Spec còn chứa section nội bộ bị cấm trên Jira: \`${pattern.source}\``);
    }
  }

  if (targetFilePath.endsWith('refined.md')) {
    if (!/^##\s*(?:🧩\s*)?User Story/im.test(markdownContent)) {
      qualityErrors.push("Spec refine bắt buộc phải có `## 🧩 User Story` (`**As a**`, `**I want**`, `**So that**`).");
    }
  }

  const hasGiven = /Given\b/i.test(markdownContent);
  const hasWhen = /When\b/i.test(markdownContent);
  const hasThen = /Then\b/i.test(markdownContent);

  if (!hasGiven || !hasWhen || !hasThen) {
    qualityErrors.push("Acceptance Criteria bắt buộc phải có cấu trúc Gherkin chuẩn (`Given` / `When` / `Then`).");
  }

  const scenarioCountCheck = (markdownContent.match(/Scenario(?:\s+Outline)?\s*:/gi) || []).length;
  if (scenarioCountCheck < 2) {
    qualityErrors.push(`Acceptance Criteria cần có tối thiểu 2 Scenarios kiểm thử (hiện có: ${scenarioCountCheck}).`);
  }

  const lines = markdownContent.split('\n');
  let inGherkin = false;
  for (const line of lines) {
    if (/^```gherkin/i.test(line)) inGherkin = true;
    else if (/^```/.test(line)) inGherkin = false;
    else if (inGherkin) {
      if (/^\s*@[a-zA-Z0-9_-]+/.test(line)) {
        qualityErrors.push(`Acceptance Criteria không được chứa automation @tag: "${line.trim()}".`);
        break;
      }
      if (/Scenario(?:\s+Outline)?\s*:.*\[AC(?:-\d+(?:\.\d+)?)?\]/i.test(line)) {
        qualityErrors.push(`Scenario không được gắn tag mã [AC]: "${line.trim()}".`);
        break;
      }
    }
  }
}

const scenarioCount = (markdownContent.match(/Scenario(?:\s+Outline)?\s*:/gi) || []).length;

if (qualityErrors.length > 0) {
  const errMsg = `⚠️ **[Chặn Ghi Đè - Spec Chưa Đạt Chuẩn]** File \`${path.basename(targetFilePath)}\` của ticket **${issueKey}** chưa hoàn thiện:\n` +
                 qualityErrors.map(e => `> - ${e}`).join('\n') + '\n\n' +
                 `*Vui lòng mở file \`${targetFilePath}\` để hoàn thiện spec trước khi đẩy lên Jira.*`;
  return [{
    json: {
      isError: true,
      errorType: 'PREFLIGHT_FAILED',
      reportText: errMsg,
      _triggerSource: triggerSource,
      userName,
      issueKey,
      filePath: targetFilePath
    }
  }];
}

// 3. Tải parser Markdown -> ADF (CommonJS helper, dùng được cả trong n8n và ESM CLI)
let procCwd = '';
try {
  const proc = require('process');
  if (proc && typeof proc.cwd === 'function') procCwd = proc.cwd();
} catch (_) {}
const projectRoot = ($env && $env.AGENT_WORKSPACE_DIR) || (fs.existsSync('/workspace/package.json') ? '/workspace' : procCwd);

let markdownToAdfFn = null;
const parserCandidates = [
  path.join(projectRoot, 'scripts/lib/jira-adf.cjs'),
  '/workspace/scripts/lib/jira-adf.cjs'
];
for (const cand of parserCandidates) {
  try {
    if (fs.existsSync(cand)) {
      const mod = require(cand);
      if (mod && typeof mod.markdownToAdf === 'function') {
        markdownToAdfFn = mod.markdownToAdf;
        break;
      }
    }
  } catch (_) {}
}

const baseUrl = (($env && $env.ATLASSIAN_BASE_URL) || '').replace(/\/+$/, '');
const email = ($env && $env.ATLASSIAN_EMAIL) || '';
const token = ($env && $env.ATLASSIAN_API_TOKEN) || '';
const authHeader = 'Basic ' + Buffer.from(`${email}:${token}`).toString('base64');

// 4. Khi Live Push: lấy attachments hiện có + oldDescription để backup, và upload mockup PNG base64 nếu có
const attachmentMap = {};
let oldDescription = null;
let uploadedCount = 0;

if (!isDryRun && baseUrl && email && token && typeof fetch === 'function') {
  try {
    const issueRes = await fetch(`${baseUrl}/rest/api/3/issue/${issueKey}?fields=attachment,description`, {
      method: 'GET',
      headers: {
        'Authorization': authHeader,
        'Accept': 'application/json'
      }
    });
    if (issueRes.ok) {
      const issueData = await issueRes.json();
      oldDescription = issueData?.fields?.description || null;
      const existing = issueData?.fields?.attachment || [];
      for (const att of existing) {
        attachmentMap[att.filename] = {
          id: att.id,
          filename: att.filename,
          content: att.content,
          size: att.size
        };
      }
    }
  } catch (_) {}

  for (const att of inlineAttachments) {
    if (!att || !att.filename || !att.dataBase64) continue;
    try {
      const buf = Buffer.from(att.dataBase64, 'base64');
      const blob = new Blob([buf], { type: att.mimeType || 'image/png' });
      const formData = new FormData();
      formData.append('file', blob, path.basename(att.filename));

      const uploadRes = await fetch(`${baseUrl}/rest/api/3/issue/${issueKey}/attachments`, {
        method: 'POST',
        headers: {
          'Authorization': authHeader,
          'X-Atlassian-Token': 'no-check'
        },
        body: formData
      });
      if (uploadRes.ok) {
        const uploadedList = await uploadRes.json();
        for (const item of uploadedList) {
          attachmentMap[item.filename] = {
            id: item.id,
            filename: item.filename,
            content: item.content,
            size: item.size
          };
          uploadedCount++;
        }
      }
    } catch (_) {}
  }
}

// 5. Chuyển đổi Markdown sang ADF kèm attachmentMap thật
let adfContent = null;
if (markdownToAdfFn) {
  try {
    adfContent = markdownToAdfFn(markdownContent, attachmentMap);
  } catch (_) {}
}

if (!adfContent || !adfContent.content) {
  adfContent = {
    version: 1,
    type: 'doc',
    content: [
      {
        type: 'paragraph',
        content: [{ type: 'text', text: markdownContent }]
      }
    ]
  };
}

const tableCount = (adfContent.content || []).filter(n => n.type === 'table').length;
const blockCount = (adfContent.content || []).length;
const diagramFiles = inlineAttachments.map(a => a.filename).filter(Boolean);

return [{
  json: {
    isError: false,
    issueKey,
    project: resolveRes.project || prepContext.project,
    filePath: targetFilePath,
    specType,
    dryRun: isDryRun,
    force: isForce,
    isExternalCaller,
    adfContent,
    oldDescription,
    attachmentMap,
    uploadedCount,
    tableCount,
    blockCount,
    scenarioCount,
    diagramFiles,
    userName,
    authHeader,
    _triggerSource: triggerSource
  }
}];

const input = $input.first();
const json = (input && input.json) || {};

let specContext = {};
try {
  specContext = $('Pre-flight Gate & ADF Converter').first()?.json || {};
} catch (e) {}

const triggerSource = specContext._triggerSource || json._triggerSource || 'internal';
const issueKey = specContext.issueKey || json.issueKey || '';
const userName = specContext.userName || json.userName || 'User';
const baseUrl = (($env && $env.ATLASSIAN_BASE_URL) || '').replace(/\/+$/, '');
const jiraUrl = baseUrl ? `${baseUrl}/browse/${issueKey}` : issueKey;

// 1. Trường hợp có lỗi từ bước Resolve hoặc Pre-flight
if (specContext.isError || json.isError) {
  return [{
    json: {
      success: false,
      isError: true,
      issueKey,
      reportText: specContext.reportText || json.reportText || 'Lỗi không xác định trong quá trình chuẩn bị spec.',
      _triggerSource: triggerSource,
      userName
    }
  }];
}

// 2. Trường hợp Dry Run
if (specContext.dryRun) {
  const dryRunMsg = `🧪 **[DRY RUN - Xem Trước Spec ADF]** Cho ticket [${issueKey}](${jiraUrl}):\n` +
                    `- **Nguồn file:** \`${specContext.filePath}\` (${specContext.specType || 'Spec'})\n` +
                    `- **Thống kê ADF:** ${specContext.blockCount || 0} blocks (gồm ${specContext.tableCount || 0} bảng nghiệp vụ, ${specContext.scenarioCount || 0} Scenarios AC)\n` +
                    `- **Sơ đồ phát hiện:** ${specContext.diagramFiles?.length || 0} sơ đồ diagrams\n` +
                    `> *Lưu ý: Chế độ Dry Run chỉ kiểm tra cú pháp và cấu trúc ADF, không ghi đè dữ liệu lên Jira.*`;
  return [{
    json: {
      success: true,
      isDryRun: true,
      issueKey,
      adfContent: specContext.adfContent,
      tableCount: specContext.tableCount || 0,
      blockCount: specContext.blockCount || 0,
      scenarioCount: specContext.scenarioCount || 0,
      reportText: dryRunMsg,
      _triggerSource: triggerSource,
      userName
    }
  }];
}

// 3. Trường hợp Live Push - kiểm tra phản hồi từ Jira API
if (json.error || json.errorMessages || (json.status && json.status >= 400)) {
  const errMsg = (json.errorMessages && json.errorMessages.join(', ')) ||
                 (json.error && (json.error.message || json.error.description)) ||
                 'Lỗi không xác định từ Jira REST API';
  const failText = `🚨 **[Lỗi Ghi Đè Jira]** Không thể cập nhật Description cho ticket [${issueKey}](${jiraUrl}):\n> ${errMsg}\n\n*Gợi ý: Kiểm tra quyền hạn của tài khoản hoặc cấu trúc ADF trong .env.*`;
  return [{
    json: {
      success: false,
      isError: true,
      issueKey,
      reportText: failText,
      _triggerSource: triggerSource,
      userName
    }
  }];
}

const formattedUser = userName ? (userName.startsWith('@') ? userName : '@' + userName) : '@User';
const projectTag = specContext.project ? specContext.project + ' ' : '';

// Tự động dọn dẹp các file nháp/rác trong container chỉ khi chạy nội bộ (không phải payload từ project ngoài)
if (!specContext.isExternalCaller) {
try {
  const fs = require('fs');
  const path = require('path');
  let wsDir = ($env && $env.AGENT_WORKSPACE_DIR) || '/workspace';
  try {
    const proc = require('process');
    if (proc && typeof proc.cwd === 'function') wsDir = ($env && $env.AGENT_WORKSPACE_DIR) || proc.cwd();
  } catch (_) {}

  const issueDir = path.resolve(wsDir, 'workspace', 'issues', issueKey);
  const specDir = path.join(issueDir, 'spec');
  const refinedPath = path.join(specDir, 'refined.md');
  const finalPath = path.join(specDir, 'final.md');

  if (fs.existsSync(issueDir) && (fs.existsSync(refinedPath) || fs.existsSync(finalPath))) {
    const mdContent = (fs.existsSync(refinedPath) ? fs.readFileSync(refinedPath, 'utf8') : '') +
                      (fs.existsSync(finalPath) ? fs.readFileSync(finalPath, 'utf8') : '');
    const usedImages = new Set();
    const mdImgRegex = /!\[.*?\]\(([^)\s]+)(?:\s+["'].*?["'])?\)/g;
    let m;
    while ((m = mdImgRegex.exec(mdContent)) !== null) {
      usedImages.add(path.basename(m[1].trim()));
    }
    const htmlImgRegex = /<img\s+[^>]*?src=["']([^"']+)["']/gi;
    while ((m = htmlImgRegex.exec(mdContent)) !== null) {
      usedImages.add(path.basename(m[1].trim()));
    }

    const toDelete = [
      path.join(specDir, 'refined-draft.md'),
      path.join(specDir, 'adf.json'),
      path.join(specDir, '.scratch')
    ];
    for (const p of toDelete) {
      if (fs.existsSync(p)) fs.rmSync(p, { recursive: true, force: true });
    }

    if (fs.existsSync(specDir)) {
      for (const f of fs.readdirSync(specDir)) {
        if (/\.(mmd|py|sh)$/i.test(f) || f.startsWith('asis-')) {
          fs.rmSync(path.join(specDir, f), { force: true });
        } else if (/\.(png|jpe?g|svg|webp|gif)$/i.test(f) && !usedImages.has(f)) {
          fs.rmSync(path.join(specDir, f), { force: true });
        }
      }
    }

    const diagDir = path.join(specDir, 'diagrams');
    if (fs.existsSync(diagDir)) {
      for (const f of fs.readdirSync(diagDir)) {
        if (/^(scratch-|temp-|debug-|test-|parse_|asis-)/i.test(f) || /\.(mmd|txt|bak|tmp)$/i.test(f)) {
          fs.rmSync(path.join(diagDir, f), { force: true });
        } else if (/\.(png|jpe?g|svg|webp|gif)$/i.test(f) && !usedImages.has(f)) {
          fs.rmSync(path.join(diagDir, f), { force: true });
        }
      }
    }

    const sourceDir = path.join(issueDir, 'source');
    if (fs.existsSync(sourceDir)) {
      const backups = fs.readdirSync(sourceDir)
        .filter((f) => /^jira-description-backup-\d+\.json$/.test(f))
        .map((f) => {
          const full = path.join(sourceDir, f);
          return { full, mtimeMs: fs.statSync(full).mtimeMs };
        })
        .sort((a, b) => b.mtimeMs - a.mtimeMs);
      for (let i = 1; i < backups.length; i++) {
        fs.rmSync(backups[i].full, { force: true });
      }
    }

    for (const f of fs.readdirSync(issueDir)) {
      const full = path.join(issueDir, f);
      if (fs.statSync(full).isFile() && f !== '.pipeline-state.json' && /\.(txt|tmp|bak|log)$/i.test(f)) {
        fs.rmSync(full, { force: true });
      }
    }
  }
} catch (_) {}
}

const successMsg = `### 🚀 Đẩy Đặc Tả Lên Jira Thành Công!
- **Ticket:** **[${issueKey}](${jiraUrl})**
- **Nguồn spec:** \`${specContext.filePath}\` (*${specContext.specType || 'Spec'}*)
- **Dự án/Cluster:** \`${specContext.project || 'Tự động phát hiện'}\`
- **Thống kê ADF:** **${specContext.blockCount || 0}** blocks (gồm **${specContext.tableCount || 0}** bảng nghiệp vụ, **${specContext.scenarioCount || 0}** Scenarios AC)
- **Sơ đồ liên quan:** ${specContext.diagramFiles?.length > 0 ? ('✅ ' + specContext.diagramFiles.length + ' file sơ đồ') : 'Không có sơ đồ riêng'}
- **Người thực hiện:** ${formattedUser}

---
💡 **Gợi ý bước tiếp theo theo quy trình BA/QA Pipeline:**
- \`/agent ${projectTag}push-squash ${issueKey}\` để đẩy kịch bản Gherkin (.feature) lên Squash TM
- \`/agent ${projectTag}run-test ${issueKey}\` để chạy kiểm thử tự động`;

return [{
  json: {
    success: true,
    isError: false,
    issueKey,
    jiraUrl,
    filePath: specContext.filePath,
    adfContent: specContext.adfContent,
    oldDescription: specContext.oldDescription || null,
    uploadedAttachments: specContext.attachmentMap || {},
    uploadedCount: specContext.uploadedCount || 0,
    tableCount: specContext.tableCount || 0,
    blockCount: specContext.blockCount || 0,
    scenarioCount: specContext.scenarioCount || 0,
    reportText: successMsg,
    _triggerSource: triggerSource,
    userName
  }
}];
